import { sortTimeline, timelineCompare } from "../../src/domain/Timeline.js"

type TimelineLike = {
  readonly timestamp: string
  readonly eventType: string
  readonly subject: string
}

const event = (timestamp: string, eventType: string, subject: string): TimelineLike => ({
  timestamp,
  eventType,
  subject
})

describe("timelineCompare", () => {
  it("orders by timestamp first", () => {
    const earlier = event("2026-01-01T00:00:00.000Z", "alert", "checkout")
    const later = event("2026-01-01T00:00:01.000Z", "alert", "checkout")
    expect(timelineCompare(earlier, later)).toBeLessThan(0)
    expect(timelineCompare(later, earlier)).toBeGreaterThan(0)
  })

  it("orders by eventType when timestamps match", () => {
    const alpha = event("2026-01-01T00:00:00.000Z", "alert", "checkout")
    const beta = event("2026-01-01T00:00:00.000Z", "deploy", "checkout")
    expect(timelineCompare(alpha, beta)).toBeLessThan(0)
    expect(timelineCompare(beta, alpha)).toBeGreaterThan(0)
  })

  it("orders by subject when timestamp and eventType match", () => {
    const alpha = event("2026-01-01T00:00:00.000Z", "alert", "alpha")
    const beta = event("2026-01-01T00:00:00.000Z", "alert", "beta")
    expect(timelineCompare(alpha, beta)).toBeLessThan(0)
    expect(timelineCompare(beta, alpha)).toBeGreaterThan(0)
  })

